// Synthetic fixtures, never customer or real financial data.
export const SAMPLE_LABEL =
  "sample data generated by scripts/gen-payouts.ts and scripts/gen-vendors.ts";
export function payoutSample(week: number) {
  let seed = 3100 + week;
  const random = () =>
    (seed = (1664525 * seed + 1013904223) >>> 0) / 4294967296;
  const payouts = ["payout_id,date,gross,fee,net,status"],
    bank = ["reference,booking_date,amount,description"];
  for (let i = 0; i < 25; i++) {
    const day = 1 + ((week * 7 + i) % 28);
    const date = `2026-10-${String(day).padStart(2, "0")}`;
    const gross =
      i % 9 === 0
        ? -Math.round(random() * 10000) / 100
        : Math.round((100 + random() * 1000) * 100) / 100;
    const fee = gross < 0 ? 0 : Math.round(gross * 0.029 * 100) / 100;
    const net = Math.round((gross - fee) * 100) / 100;
    const id = `po_${week}_${i}`;
    payouts.push(
      `${id},${date},${gross.toFixed(2)},${fee.toFixed(2)},${net.toFixed(2)},${gross < 0 ? "refund" : "paid"}`,
    );
    const amount =
      net < 0 ? `($${Math.abs(net).toFixed(2)})` : `$${net.toFixed(2)}`;
    bank.push(
      `${id},${String(day).padStart(2, "0")}/10/2026,${amount},Stripe ${gross < 0 ? "refund" : "payout"}`,
    );
  }
  return { payouts: payouts.join("\n") + "\n", bank: bank.join("\n") + "\n" };
}
export function vendorSample(week: number) {
  const lines = [" SKU ,Vendor,Price,Unit"];
  for (let i = 0; i < 25; i++) {
    const row = ` sku-${i} ,  Vendor   ${i % 4}  ,"$${(1000 + week * 10 + i + 0.25).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}",${i % 2 ? "EA" : "each"}`;
    lines.push(row);
    if (i % 7 === 0) lines.push(row);
  }
  return lines.join("\n") + "\n";
}
